import{_ as a,o as e,c as d,a0 as r}from"./chunks/framework.BpJS36ta.js";const h=JSON.parse('{"title":"Module Grammar","description":"","frontmatter":{},"headers":[],"relativePath":"modules/grammar/index.md","filePath":"modules/grammar/index.md"}'),m={name:"modules/grammar/index.md"};function o(s,t,n,i,l,u){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="module-grammar" tabindex="-1">Module Grammar <a class="header-anchor" href="#module-grammar" aria-label="Permalink to &quot;Module Grammar&quot;">​</a></h1><p>Dokumentasi grammar &amp; implementasi untuk modul bawaan Rupa: struktur AST yang dibentuk parser, bentuk module object, dan catatan implementasi native. Untuk dokumentasi penggunaan per modul, lihat <a href="./../syntax/">Modules</a>.</p><h2 id="pola-umum" tabindex="-1">Pola umum <a class="header-anchor" href="#pola-umum" aria-label="Permalink to &quot;Pola umum&quot;">​</a></h2><p>Semua import modul mengikuti satu pola grammar:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import os from rupa      → NODE_MOD (chain)</span></span>
<span class="line"><span>import math from rupa</span></span>
<span class="line"><span>import { join } from rupa.sys</span></span></code></pre></div><p>Interpreter menginisialisasi modul dan mendaftarkan fungsinya sebagai <code>VALUE_NATIVE_FUNCTION</code> (native) atau object namespace bahasa Rupa (mis. <code>math</code>, <code>sys</code>, <code>fs</code> yang ditulis di <code>stdlib/</code>). Detail mekanisme: <a href="./../../grammar/module.html">Grammar — Module</a>.</p><h2 id="grammar-per-modul" tabindex="-1">Grammar per modul <a class="header-anchor" href="#grammar-per-modul" aria-label="Permalink to &quot;Grammar per modul&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Modul</th><th>Grammar</th><th>Catatan implementasi</th></tr></thead><tbody><tr><td><a href="./os.html">os</a></td><td>import statement, module object, native fn</td><td>akses sistem POSIX</td></tr><tr><td><a href="./io.html">io</a></td><td>—</td><td>input/toNumber</td></tr><tr><td><a href="./json.html">json</a></td><td>—</td><td>stringify/parse</td></tr><tr><td><a href="./string.html">string</a></td><td>—</td><td>manipulasi string</td></tr><tr><td><a href="./math.html">math</a></td><td>—</td><td>ditulis bahasa Rupa (stdlib)</td></tr><tr><td><a href="./thread.html">thread</a></td><td>AST + module structure</td><td><code>thread.create()</code> hanya menerima native fn</td></tr><tr><td><a href="./http.html">http</a></td><td>AST + module structure</td><td>server blocking; handler via queue thread-safe</td></tr><tr><td><a href="./datetime.html">datetime</a></td><td>AST + module structure</td><td>waktu lokal &amp; format</td></tr><tr><td><a href="./regex.html">regex</a></td><td>AST + module structure</td><td>match/test/replace/groups</td></tr><tr><td><a href="./crypto.html">crypto</a></td><td>AST + module structure</td><td>hash/hmac (OpenSSL)</td></tr><tr><td><a href="./net.html">net</a></td><td>AST + module structure</td><td>TCP client/server</td></tr></tbody></table><p>Modul <code>sys</code>, <code>fs</code>, <code>database</code> ditulis murni dengan bahasa Rupa di atas modul native (<code>os</code>, <code>fsbase</code>) sehingga tidak punya grammar khusus — mereka package biasa dengan <code>export</code> (lihat <a href="./../../syntax/export.html">Syntax — Export</a>).</p>`,9)])])}const c=a(m,[["render",o]]);export{h as __pageData,c as default};
